create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key default gen_random_uuid(),name text not null default 'Your Name',professional_title text not null default 'Software Developer',short_bio text not null default '',about text not null default '',location text not null default '',email text not null default '',phone text not null default '',profile_image_url text not null default '',cv_url text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,description text not null default '',icon text not null default '',display_order int not null default 0,is_visible boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id) on delete set null,title text not null,slug text not null unique,short_description text not null default '',description text not null default '',image_url text not null default '',github_url text not null default '',demo_url text not null default '',featured boolean not null default false,published boolean not null default false,display_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.technologies(id uuid primary key default gen_random_uuid(),name text not null unique,icon text not null default '',created_at timestamptz not null default now());
create table if not exists public.project_technologies(project_id uuid not null references public.projects(id) on delete cascade,technology_id uuid not null references public.technologies(id) on delete cascade,primary key(project_id,technology_id));
create table if not exists public.skills(id uuid primary key default gen_random_uuid(),name text not null,category text not null default '',level int check(level between 0 and 100),icon_url text not null default '',display_order int not null default 0,is_visible boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.experience(id uuid primary key default gen_random_uuid(),company text not null,position text not null,location text not null default '',description text not null default '',start_date date,end_date date,current boolean not null default false,technologies text not null default '',display_order int not null default 0,is_visible boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.education(id uuid primary key default gen_random_uuid(),institution text not null,degree text not null,field text not null default '',description text not null default '',location text not null default '',start_date date,end_date date,current boolean not null default false,display_order int not null default 0,is_visible boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.achievements(id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',date date,organization text not null default '',image_url text not null default '',display_order int not null default 0,is_visible boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.social_links(id uuid primary key default gen_random_uuid(),platform text not null,url text not null,icon text not null default '',display_order int not null default 0,is_visible boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.contact_messages(id uuid primary key default gen_random_uuid(),name text not null,email text not null,subject text not null,message text not null,is_read boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.site_settings(id uuid primary key default gen_random_uuid(),site_name text not null default 'Portfolio',site_description text not null default '',logo_url text not null default '',favicon_url text not null default '',seo_title text not null default '',seo_description text not null default '',seo_keywords text not null default '',primary_color text not null default '#23483e',secondary_color text not null default '#a5c56a',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists projects_public_order_idx on public.projects(published,display_order);create index if not exists projects_category_idx on public.projects(category_id);create index if not exists messages_recent_idx on public.contact_messages(created_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end $$;
drop trigger if exists profiles_updated_at on public.profiles;create trigger profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at();
drop trigger if exists projects_updated_at on public.projects;create trigger projects_updated_at before update on public.projects for each row execute function public.set_updated_at();
drop trigger if exists experience_updated_at on public.experience;create trigger experience_updated_at before update on public.experience for each row execute function public.set_updated_at();
drop trigger if exists education_updated_at on public.education;create trigger education_updated_at before update on public.education for each row execute function public.set_updated_at();
drop trigger if exists site_settings_updated_at on public.site_settings;create trigger site_settings_updated_at before update on public.site_settings for each row execute function public.set_updated_at();
do $$ declare t text; begin foreach t in array array['profiles','categories','projects','technologies','project_technologies','skills','experience','education','achievements','social_links','contact_messages','site_settings'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
-- Portfolio administration uses Supabase Auth. Create only trusted admin accounts in the Supabase dashboard.
do $$ declare t text; begin foreach t in array array['profiles','categories','projects','technologies','project_technologies','skills','experience','education','achievements','social_links','contact_messages','site_settings'] loop execute format('drop policy if exists admin_all on public.%I',t);execute format('create policy admin_all on public.%I for all to authenticated using ((auth.jwt()->''app_metadata''->>''role'') = ''admin'') with check ((auth.jwt()->''app_metadata''->>''role'') = ''admin'')',t); end loop; end $$;
create policy public_profile_read on public.profiles for select to anon,authenticated using (true);
create policy public_categories_read on public.categories for select to anon,authenticated using (is_visible);
create policy public_projects_read on public.projects for select to anon,authenticated using (published);
create policy public_technologies_read on public.technologies for select to anon,authenticated using (true);
create policy public_project_technologies_read on public.project_technologies for select to anon,authenticated using (exists(select 1 from public.projects p where p.id=project_id and p.published));
create policy public_skills_read on public.skills for select to anon,authenticated using (is_visible);
create policy public_experience_read on public.experience for select to anon,authenticated using (is_visible);
create policy public_education_read on public.education for select to anon,authenticated using (is_visible);
create policy public_achievements_read on public.achievements for select to anon,authenticated using (is_visible);
create policy public_social_read on public.social_links for select to anon,authenticated using (is_visible);
create policy public_message_insert on public.contact_messages for insert to anon,authenticated with check (length(name) between 1 and 100 and length(email) between 3 and 254 and length(subject) between 1 and 180 and length(message) between 1 and 5000);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('profile','profile',true,5242880,array['image/jpeg','image/png','image/webp']),('projects','projects',true,8388608,array['image/jpeg','image/png','image/webp']),('achievements','achievements',true,5242880,array['image/jpeg','image/png','image/webp']),('skills','skills',true,2097152,array['image/jpeg','image/png','image/webp']),('documents','documents',true,15728640,array['application/pdf']) on conflict(id) do nothing;
create policy public_storage_read on storage.objects for select to anon,authenticated using (bucket_id in ('profile','projects','achievements','skills','documents'));
create policy admin_storage_write on storage.objects for all to authenticated using (bucket_id in ('profile','projects','achievements','skills','documents')) with check (bucket_id in ('profile','projects','achievements','skills','documents'));
